cat <<'EOF' > compile.sh
#!/usr/bin/env bash
set -e
# Compile the small CLI
gcc -O2 -s main.c -o executable
chmod +x executable
EOF

chmod +x compile.sh

# Create .gitignore
cat <<'EOF' > .gitignore
executable
*.o
EOF

# Add files to git
git add main.c compile.sh .gitignore
git commit -m "Add reimplementation of CLI help/version and build script" || true

# Build
./compile.sh

# Test outputs
./executable --help > help_new.txt
./executable -version > version_new.txt

echo "----HELP----"
sed -n '1,40p' help_new.txt
echo "----VERSION----"
cat version_new.txt
EOF"}

